/** Generated by scaffold-crud-pages. Query hooks for QuizSessions.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchQuizSessionsList,
  fetchQuizSessionsById,
  createQuizSessions,
  updateQuizSessions,
  deleteQuizSessions,
  type FetchQuizSessionsListParams,
} from '~/services/httpServices/quizSessionsService';
import type { CreateQuizSessionsRequest, UpdateQuizSessionsRequest } from '~/types/quiz-sessions';

const DOMAIN = 'quizSessions';

export function useQuizSessionsList(params?: FetchQuizSessionsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchQuizSessionsList(params),
  });
}

export function useQuizSessions(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchQuizSessionsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateQuizSessions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateQuizSessionsRequest) => createQuizSessions(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateQuizSessions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateQuizSessionsRequest }) =>
      updateQuizSessions(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteQuizSessions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteQuizSessions(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
